const $=id=>document.getElementById(id);
const scenes=[
{title:'De wortelkathedraal',file:'roots',ratio:1.5,tag:'01 · HET GEHEUGEN VAN HET WOUD',intro:'Onder deze wortels meet niemand de tijd. Raak een lichtpunt aan: elk leven bewaart een verhaal.',alt:'Een wit woudhert en een vos bij een reusachtige, overgroeide boomkathedraal; robots verzorgen de planten.',points:[{x:20,y:47,name:'Het kroonhert',text:'In zijn gewei draagt het kroonhert zaden van de oudste bomen. Waar het rust, begint een nieuw stukje woud.'},{x:39,y:68,name:'De wortelvos',text:'Hij hoort het water diep onder de aarde. De tuiniers volgen zijn spoor om dorstige wortels te vinden.'},{x:70,y:58,name:'De stille tuiniers',text:'Hun handen zijn van metaal, hun opdracht is levend: zorg dat elke open plek opnieuw kan groeien.'},{x:55,y:21,name:'Het hart van de boom',text:'De oude kern bewaart de geluiden van verdwenen bossen. Soms klinkt tussen de bladeren een vogel die niemand meer kent.'}]},
{title:'De lichtpoort',file:'gate',ratio:1.5,tag:'02 · TUSSEN TWEE WERELDEN',intro:'Het water weerspiegelt een bos dat hier niet groeit. De bewoners kennen de weg door het licht.',alt:'Een turquoise poort in een bosrijke bergvallei, met twee lichtgevende boswezens en een uil met een mechanische vleugel.',points:[{x:22,y:71,name:'De schemerdrinker',text:'Zijn lichtvlekken worden helderder wanneer de poort ontwaakt. Hij proeft aan het water welk seizoen aan de overkant wacht.'},{x:39,y:56,name:'De drempelwachter',text:'Ze blijft luisteren tot beide bossen hetzelfde ritme hebben. Pas dan durven de kleintjes de doorgang over.'},{x:11,y:22,name:'De zilvervleugel',text:'Een storm nam haar vleugel. De moswachter maakte een nieuwe. Nu brengt ze zaden naar valleien voorbij de poort.'},{x:66,y:42,name:'De levende doorgang',text:'Wortels hielden de stenen bijeen toen de bouwers verdwenen. De sterrenmotor werkt alleen zolang het woud gezond blijft.'}]},
{title:'De zwevende tuinen',file:'gardens',ratio:1672/941,tag:'03 · WAAR DE AARDE LEERT VLIEGEN',intro:'Boven de mist hangen tuinen aan niets. Het is stil, tot een enorme vleugel de lucht langzaam verplaatst.',alt:'Gevederde draken vliegen tussen bosrijke zwevende eilanden met watervallen, slanke torens en kleine verzorgingsdrones.',points:[{x:29,y:35,name:'De bladerdraak',text:'Zijn veren dragen de kleuren van het bladerdak. Op de warme lucht tussen de eilanden kan hij dagenlang zweven.'},{x:53,y:16,name:'De jonge reiziger',text:'Deze jonge draak volgt zijn eerste route boven de wolken. De watervallen wijzen hem de weg terug naar het nest.'},{x:61,y:39,name:'De zaadbewaarder',text:'Kleine drones brengen stuifmeel van eiland naar eiland. Zonder hun dagelijkse reizen zouden de zwevende bossen langzaam verstillen.'},{x:80,y:65,name:'De hangende wortels',text:'Onder het mos fluistert een magnetische ring. De wortels groeien eromheen, als vingers die iets kostbaars vasthouden.'}]},
{title:'De moswachter',file:'guardian',ratio:1.5,tag:'04 · DE ZACHTHEID VAN EEN REUS',intro:'Een reus knielt. Op zijn hand staat iets dat hij met al zijn kracht nooit zelf zou kunnen maken: nieuw leven.',alt:'Een enorme met mos bedekte robot houdt een sapling en klein boswezen in zijn hand; herten en robotbijen leven om hem heen.',points:[{x:35,y:25,name:'De moswachter',text:'Hij werd gebouwd om muren te breken. Al duizend jaar gebruikt hij dezelfde handen om nesten te beschermen en bomen recht te zetten.'},{x:73,y:46,name:'Het bladortje',text:'Zes kleine poten, twee oren als bladeren. Het bladortje maakt zijn nest op de schouder van de reus, waar geen storm het bereikt.'},{x:14,y:68,name:'De valleiherten',text:'Ze schrikken niet van zijn voetstappen. Voor hen is de moswachter gewoon een heuvel die af en toe van plaats verandert.'},{x:91,y:60,name:'De zoemende helpers',text:'Hun vleugels zijn gemaakt, hun werk is natuurlijk. Elke bloem krijgt bezoek, ook wanneer de echte bijen schuilen voor de regen.'}]}
];
const dialog=$('vision-dialog'),picture=$('vision-picture'),img=$('vision-image');let current=0,near=-1,seen=new Set(),clean=false,previousFocus=null;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function caption(name,text,tag){$('vision-creature').textContent=name;$('vision-description').textContent=text;$('vision-tag').textContent=tag}
function fit(){let stage=$('vision-stage'),r=stage.getBoundingClientRect(),ratio=scenes[current].ratio,w=Math.min(r.width,r.height*ratio);picture.style.width=w+'px';picture.style.height=w/ratio+'px'}
function select(i){i=(i+4)%4;if(window.elyndraGame&&!window.elyndraGame.unlocked(i)){window.elyndraStartPuzzle(i);return;}current=i;const s=scenes[current];seen.add(current);$('vision-title').textContent=s.title;$('vision-count').textContent=(window.elyndraGame?window.elyndraGame.count():seen.size)+'/4';$('vision-next').textContent=current===3?'Naar de wortelkathedraal ↗':'Volgend visioen →';caption(s.title,s.intro,s.tag);$('vision-points').replaceChildren();s.points.forEach((p,j)=>{let b=document.createElement('button');b.className='vision-point';b.style.left=p.x+'%';b.style.top=p.y+'%';b.setAttribute('aria-label','Ontmoet '+p.name);b.setAttribute('aria-pressed','false');b.innerHTML='<span>'+(j+1)+'</span>';b.onclick=()=>{for(let el of $('vision-points').children)el.setAttribute('aria-pressed','false');b.setAttribute('aria-pressed','true');caption(p.name,p.text,'BEWONER VAN ELYNDRA · '+(j+1)+' / '+s.points.length)};$('vision-points').appendChild(b)});
$('vision-loading').hidden=false;picture.classList.remove('revealed');img.alt=s.alt;img.onload=()=>{$('vision-loading').hidden=true;fit();picture.classList.add('revealed')};img.onerror=()=>{$('vision-loading').hidden=false;$('vision-loading').textContent='Dit visioen kon niet laden. Kies het opnieuw of keer terug naar het woud.'};img.src='visions/'+s.file+'.webp';if(img.complete&&img.naturalWidth)img.onload();for(let [j,b]of [...$('vision-rail').children].entries()){b.setAttribute('aria-current',j===current?'true':'false');b.classList.toggle('seen',seen.has(j))}fit();}
function setClean(value){clean=value;dialog.classList.toggle('clean',clean);$('vision-clean').textContent=clean?'Toon de verhalen':'Alleen het beeld';$('vision-clean').setAttribute('aria-pressed',String(clean));requestAnimationFrame(fit)}
function open(i){if(window.elyndraGame&&!window.elyndraGame.unlocked(i)){window.elyndraStartPuzzle(i);return;}previousFocus=document.activeElement;window.elyndraVisionOpen=true;dispatchEvent(new Event('elyndra-vision-open'));if(!dialog.open)dialog.showModal();setClean(false);select(i);$('vision-exit').focus();}
function close(){dialog.close()}
dialog.addEventListener('close',()=>{window.elyndraVisionOpen=!!document.querySelector('dialog[open]');picture.style.transform='';if(!window.elyndraVisionOpen)previousFocus?.focus()});$('vision-exit').onclick=close;$('vision-clean').onclick=()=>setClean(!clean);$('vision-next').onclick=()=>select(current+1);$('visions-open').onclick=()=>window.elyndraStartPuzzle?window.elyndraStartPuzzle(-1):open(current);$('vision-near').onclick=()=>{if(near>=0&&near<4)open(near)};
for(let [i,s]of scenes.entries()){let b=document.createElement('button');b.className='vision-thumb';b.setAttribute('aria-label',s.title);let thumb=document.createElement('img');thumb.src='visions/'+s.file+'.webp';thumb.alt='';thumb.loading='lazy';let name=document.createElement('span');name.textContent=s.title;b.append(thumb,name);b.onclick=()=>select(i);$('vision-rail').appendChild(b)}
addEventListener('elyndra-near',e=>{near=e.detail;$('vision-near').hidden=near<0||near>3;if(near>=0&&near<4)$('vision-near').textContent=(window.elyndraGame?.unlocked(near)?'Visioen: ':'Puzzel: ')+scenes[near].title+' · V'});
addEventListener('keydown',e=>{if(e.repeat)return;if(dialog.open){if(e.code==='ArrowRight'){e.preventDefault();select(current+1)}if(e.code==='ArrowLeft'){e.preventDefault();select(current-1)}}else if(e.code==='KeyV'&&!$('quest-dialog').open){e.preventDefault();open(near>=0&&near<4?near:current)}});
$('vision-stage').addEventListener('pointermove',e=>{if(reduced||e.pointerType!=='mouse')return;let r=$('vision-stage').getBoundingClientRect();picture.style.transform=`perspective(1800px) rotateY(${((e.clientX-r.left)/r.width-.5)*1.2}deg) rotateX(${-.8*((e.clientY-r.top)/r.height-.5)}deg)`});$('vision-stage').addEventListener('pointerleave',()=>picture.style.transform='');addEventListener('resize',fit);

function updateLocks(){for(let [i,b]of [...$('vision-rail').children].entries()){let locked=window.elyndraGame&&!window.elyndraGame.unlocked(i);b.classList.toggle('locked',locked);b.setAttribute('aria-label',(locked?'Speel de puzzel voor ':'Bekijk ')+scenes[i].title);b.querySelector('span').textContent=locked?'◇ '+scenes[i].title:scenes[i].title;}if(near>=0&&near<4)$('vision-near').textContent=(window.elyndraGame?.unlocked(near)?'Visioen: ':'Puzzel: ')+scenes[near].title+' · V';}
addEventListener('elyndra-game-update',updateLocks);addEventListener('elyndra-reward',e=>open(e.detail));updateLocks();
